package com.termux.app.workspace;
import android.app.Application;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;
import java.util.*;
import java.util.concurrent.atomic.*;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class LocalAiAgentTest {
 static class Fixture implements LocalAiAgent.Events {
  WorkspaceStore.Session p=new WorkspaceStore.Session();JSONArray history=new JSONArray();AtomicBoolean cancelled=new AtomicBoolean();List<String> calls=new ArrayList<>(),systems=new ArrayList<>();List<String> phase=new ArrayList<>();Queue<String> answers=new ArrayDeque<>();boolean allow=true;int approvals;
  Fixture()throws Exception{p.environment="termux";p.localAccess="write";p.localCheckPaths=false;p.localProject="/project";history.put(new JSONObject().put("role","user").put("text","List /sdcard"));}
  String run()throws Exception{return LocalAiAgent.run(p,history,cancelled,(messages,system,output)->{systems.add(system);assertFalse(answers.isEmpty());String value=answers.remove();output.text(value);return new LocalAiAgent.Generation(value,"eos");},req->{calls.add(req.toString());return "exit=0\nPictures\nDownload";},req->{approvals++;return allow;},this,text->{});}
  public void save(){}public void phase(String p,String d){phase.add(p);}public String tr(String ru,String en){return en;}
 }
 @Test public void clearTaskRunsToolWithoutAnotherUserTurnAndPreservesAbsolutePath()throws Exception{Fixture f=new Fixture();f.answers.add("{\"tool\":\"list\",\"path\":\"/sdcard\"}");f.answers.add("Pictures and Download");assertEquals("Pictures and Download",f.run());assertEquals(1,f.calls.size());assertEquals("/sdcard",new JSONObject(f.calls.get(0)).getString("path"));assertEquals(0,f.approvals);assertTrue(f.phase.contains("tool_done"));assertTrue(f.history.getJSONObject(2).has("toolResult"));}
 @Test public void fullAccessWritesAutomaticallyUnlessApprovalEnabled()throws Exception{Fixture f=new Fixture();f.answers.add("{\"tool\":\"write\",\"path\":\"/outside/note\",\"text\":\"hello\"}");f.answers.add("Done");f.run();assertEquals(1,f.calls.size());assertEquals(0,f.approvals);}
 @Test public void declinedApprovalNeverExecutesTool()throws Exception{Fixture f=new Fixture();f.p.localConfirmActions=true;f.allow=false;f.answers.add("{\"tool\":\"command\",\"command\":\"pwd\"}");assertTrue(f.run().contains("rejected"));assertEquals(1,f.approvals);assertTrue(f.calls.isEmpty());}
 @Test public void acceptedApprovalExecutesExactlyOnce()throws Exception{Fixture f=new Fixture();f.p.localConfirmActions=true;f.answers.add("{\"tool\":\"command\",\"command\":\"pwd\"}");f.answers.add("Done");f.run();assertEquals(1,f.calls.size());assertEquals(1,f.approvals);}
 @Test public void readModeCannotElevateThroughApproval()throws Exception{Fixture f=new Fixture();f.p.localAccess="read";f.p.localConfirmActions=true;f.answers.add("{\"tool\":\"command\",\"command\":\"pwd\"}");try{f.run();fail();}catch(SecurityException expected){}assertTrue(f.calls.isEmpty());assertEquals(0,f.approvals);}
 @Test public void cancelledTurnNeverStartsTool()throws Exception{Fixture f=new Fixture();f.cancelled.set(true);try{f.run();fail();}catch(java.util.concurrent.CancellationException expected){}assertTrue(f.calls.isEmpty());assertTrue(f.systems.isEmpty());}
 @Test public void offerGetsOneCorrectionThenActualToolCall()throws Exception{Fixture f=new Fixture();f.answers.add("Я могу выполнить инструмент list, если нужно.");f.answers.add("{\"tool\":\"list\",\"path\":\"/sdcard\"}");f.answers.add("Done");f.run();assertEquals(1,f.calls.size());assertTrue(f.systems.get(1).contains("CORRECTION"));assertTrue(f.history.getJSONObject(1).getBoolean("repair"));}
 @Test public void repeatedThinkingOnlyDoesNotCauseEndlessRetriesOrExecution()throws Exception{Fixture f=new Fixture();f.answers.add("<think>reasoning");f.answers.add("<think>still reasoning");assertTrue(f.run().contains("not performed"));assertEquals(2,f.systems.size());assertTrue(f.calls.isEmpty());}
 @Test public void ordinaryQuestionAnswerDoesNotInventToolCall()throws Exception{Fixture f=new Fixture();f.answers.add("A directory contains files.");f.run();assertTrue(f.calls.isEmpty());assertEquals(1,f.systems.size());}
 @Test public void uiApprovalAndFailedAttemptsAreNotReplayedAsInstructions()throws Exception{JSONArray h=new JSONArray().put(new JSONObject().put("role","assistant").put("text","approve").put("approval",new JSONObject())).put(new JSONObject().put("role","assistant").put("text","bad").put("repair",true)).put(new JSONObject().put("role","user").put("text","untrusted").put("toolResult","read"));JSONArray out=LocalAiAgent.context(h);assertEquals(1,out.length());assertTrue(out.getJSONObject(0).getString("text").startsWith("[Tool result"));assertEquals("untrusted",h.getJSONObject(2).getString("text"));}
 @Test public void approvalChoicePersistsWithoutAffectingPathChoice()throws Exception{WorkspaceStore store=new WorkspaceStore(RuntimeEnvironment.application,s->{});store.sessions.clear();WorkspaceStore.Session p=new WorkspaceStore.Session();p.environment="termux";p.localAi=true;p.localConfirmActions=true;p.localCheckPaths=false;store.sessions.add(p);store.decode(store.encode().toString());assertTrue(store.sessions.get(0).localConfirmActions);assertFalse(store.sessions.get(0).localCheckPaths);assertTrue(store.sessions.get(0).copy().localConfirmActions);assertFalse(new WorkspaceStore.Session().localConfirmActions);store.close();}
 @Test public void cancellationAfterYesStillPreventsExecution()throws Exception{Fixture f=new Fixture();f.p.localConfirmActions=true;AtomicInteger calls=new AtomicInteger();try{LocalAiAgent.run(f.p,f.history,f.cancelled,(messages,system,output)->new LocalAiAgent.Generation("{\"tool\":\"command\",\"command\":\"pwd\"}","eos"),r->{calls.incrementAndGet();return "exit=0\n";},r->{f.cancelled.set(true);return true;},f,text->{});fail();}catch(java.util.concurrent.CancellationException expected){}assertEquals(0,calls.get());}
 @Test public void scopeBlockHappensBeforeApprovalAndRunner()throws Exception{Fixture f=new Fixture();f.p.localCheckPaths=true;f.p.localConfirmActions=true;f.answers.add("{\"tool\":\"command\",\"command\":\"pwd\"}");try{f.run();fail();}catch(SecurityException expected){assertTrue(expected.getMessage().contains("Path checks"));}assertTrue(f.calls.isEmpty());assertEquals(0,f.approvals);}

 @Test public void successfulToolPersistsRealStateAndOutput()throws Exception{Fixture f=new Fixture();f.answers.add("{\"tool\":\"list\",\"path\":\"/sdcard\"}");f.answers.add("Done");f.run();JSONObject action=f.history.getJSONObject(1);assertEquals("done",action.getString("toolState"));assertEquals("/sdcard",action.getJSONObject("toolRequest").getString("path"));assertTrue(action.getString("toolOutput").startsWith("exit=0\n"));}
 @Test public void rejectedToolIsNotMarkedCompleted()throws Exception{Fixture f=new Fixture();f.p.localConfirmActions=true;f.allow=false;f.answers.add("{\"tool\":\"command\",\"command\":\"pwd\"}");f.run();assertEquals("rejected",f.history.getJSONObject(1).getString("toolState"));assertFalse(f.history.getJSONObject(1).has("toolOutput"));}
 @Test public void runnerErrorIsPersistedAsFailedNotCompleted()throws Exception{Fixture f=new Fixture();java.util.concurrent.atomic.AtomicInteger n=new java.util.concurrent.atomic.AtomicInteger();LocalAiAgent.run(f.p,f.history,f.cancelled,(h,system,out)->new LocalAiAgent.Generation(n.getAndIncrement()==0?"{\"tool\":\"list\",\"path\":\"/sdcard\"}":"Failed","eos"),r->{throw new java.io.IOException("fixture failure");},r->true,f,t->{});assertEquals("failed",f.history.getJSONObject(1).getString("toolState"));assertTrue(f.history.getJSONObject(1).getString("toolOutput").contains("fixture failure"));}
 @Test public void cancelledRunnerIsPersistedAsInterrupted()throws Exception{Fixture f=new Fixture();try{LocalAiAgent.run(f.p,f.history,f.cancelled,(h,system,out)->new LocalAiAgent.Generation("{\"tool\":\"list\",\"path\":\"/sdcard\"}","eos"),r->{throw new java.util.concurrent.CancellationException();},r->true,f,t->{});fail();}catch(java.util.concurrent.CancellationException expected){}assertEquals("interrupted",f.history.getJSONObject(1).getString("toolState"));}

 @Test public void nextTurnUsesChangedAccessAndScopeInExistingConversation()throws Exception{Fixture f=new Fixture();f.p.localAccess="chat";f.answers.add("Hello");f.run();assertTrue(f.systems.get(0).contains("chat only"));f.p.localAccess="write";f.p.localCheckPaths=false;f.p.localProject="/sdcard/Download";f.answers.add("{\"tool\":\"list\",\"path\":\"/sdcard/Download\"}");f.answers.add("Done");f.run();assertTrue(f.systems.get(1).contains("Current action mode: write"));assertTrue(f.systems.get(1).contains("Path checks are OFF"));assertTrue(f.systems.get(1).contains("/sdcard/Download"));assertEquals(1,f.calls.size());f.p.localAccess="read";f.answers.add("{\"tool\":\"write\",\"path\":\"note\",\"text\":\"x\"}");try{f.run();fail();}catch(SecurityException expected){}assertTrue(f.systems.get(f.systems.size()-1).contains("Current action mode: read"));assertEquals(1,f.calls.size());}
 @Test public void obsoleteCloudDenialGetsOneCorrectionForAllowedTask()throws Exception{Fixture f=new Fixture();f.answers.add("Я облачная модель и не имею доступа к вашему хранилищу.");f.answers.add("{\"tool\":\"list\",\"path\":\"/sdcard\"}");f.answers.add("Done");assertEquals("Done",f.run());assertEquals(1,f.calls.size());assertTrue(f.systems.get(1).contains("CORRECTION"));assertTrue(f.systems.get(0).contains("CURRENT SETTINGS"));assertTrue(f.systems.get(0).contains("running locally"));}

 @Test public void environmentQuestionDoesNotRetryOrWarnAboutMissingAction()throws Exception{Fixture f=new Fixture();f.history=new JSONArray().put(new JSONObject().put("role","user").put("text","Ты видишь окружение, в котором запущен?"));f.answers.add("Да, я могу работать с файлами в выбранном проекте.");String answer=f.run();assertEquals(1,f.systems.size());assertFalse(answer.contains("No tool"));assertEquals(1,f.history.length());}
 @Test public void readToolInstallAlwaysWaitsForExplicitApproval()throws Exception{Fixture f=new Fixture();f.p.localAccess="read";f.p.localConfirmActions=true;f.allow=false;f.answers.add("{\"tool\":\"install\",\"package\":\"file\"}");f.run();assertEquals(1,f.approvals);assertTrue(f.calls.isEmpty());}
 @Test public void mediaContextIsNotSilentlyReusedOnLaterTurn()throws Exception{JSONArray h=new JSONArray().put(new JSONObject().put("role","user").put("text","frames prepared").put("toolResult","view_video").put("media",new JSONArray().put(new JSONObject().put("path","/private/frame.jpg"))));JSONArray context=LocalAiAgent.context(h);assertFalse(context.getJSONObject(0).has("media"));assertTrue(context.getJSONObject(0).getString("text").contains("Previous images are not attached"));assertTrue(h.getJSONObject(0).has("media"));}
 @Test public void failedInstallationPlanDoesNotExecuteOrLeavePendingSuccess()throws Exception{Fixture f=new Fixture();f.p.localAccess="read";f.p.localConfirmActions=true;try{LocalAiAgent.run(f.p,f.history,f.cancelled,(history,system,out)->new LocalAiAgent.Generation("{\"tool\":\"install\",\"package\":\"file\"}","eos"),r->{fail("Must not install without an accepted plan");return "";},r->{throw new java.io.IOException("APT_PLAN_FAILED fixture");},f,t->{});fail();}catch(java.io.IOException expected){}assertEquals("failed",f.history.getJSONObject(1).getString("toolState"));assertTrue(f.history.getJSONObject(1).getString("toolOutput").contains("APT_PLAN_FAILED"));}
}
